function drawAmbientNpcs(){const groups={0:[{x:112,y:422,p:1,c:'#8d6c64',path:'town'},{x:286,y:424,p:3,c:'#586d84',path:'town'},{x:840,y:421,p:2,c:'#93805b'}],1:[{x:132,y:420,p:1,c:'#687f67',a:'read'},{x:302,y:423,p:4,c:'#806475',a:'read'},{x:490,y:420,p:2,c:'#687584',a:'talk',path:'library'},{x:532,y:420,p:3,c:'#9a7058',a:'talk',path:'library'},{x:790,y:420,p:5,c:'#837454',a:'read'}],2:[{x:142,y:421,p:4,c:'#7d8060',a:'talk',path:'park'},{x:186,y:421,p:1,c:'#a57561',a:'talk',path:'park'},{x:824,y:421,p:3,c:'#687d86',path:'park'}],3:[{x:462,y:423,p:3,c:'#7b6880',a:'read'},{x:714,y:421,p:4,c:'#677d6c',a:'talk',path:'station'},{x:756,y:421,p:1,c:'#a4745f',a:'talk',path:'station'}],4:[{x:160,y:421,p:2,c:'#7f7358',a:'talk',path:'roof'},{x:201,y:421,p:4,c:'#667f78',a:'talk',path:'roof'},{x:847,y:422,p:3,c:'#805e6e'}],8:[{x:138,y:422,p:2,c:'#6c5d69'},{x:827,y:423,p:3,c:'#635c67'}]};for(const n of groups[scene]||[]){let px=n.x;if(n.path){const h=[...n.path].reduce((a,c)=>a+c.charCodeAt(0),0),u=(t*18+h)%240,off=u<120?u-60:180-u;px+=off}else if(n.a!=='read')px+=Math.sin(t*.6+n.p)*28;drawNpc(px,n.y,n.p,n.c,n.a||'walk',scene===8?.48:scene===1?.92:.82);if(n.a==='talk'&&Math.sin(t*2+n.p)>.35){ctx.fillStyle='#f5ead5';ctx.beginPath();ctx.roundRect(px+11,n.y-57,20,14,6);ctx.fill();ctx.fillStyle='#5a5261';ctx.beginPath();ctx.arc(px+17,n.y-50,1.4,0,Math.PI*2);ctx.arc(px+22,n.y-50,1.4,0,Math.PI*2);ctx.arc(px+27,n.y-50,1.4,0,Math.PI*2);ctx.fill()}}}
